Q: Kafka consumer list A: <pre><code>using Confluent.Kafka;
using Consumer.Data;
using Consumer.Services;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

var configuration = new ConfigurationBuilder()
    .SetBasePath(Directory.GetCurrentDirectory())
    .AddJsonFile(&quot;appsettings.json&quot;)
    .Build();
var service = new ServiceCollection();
service.AddDbContext&lt;HostileUavDbContext&gt;(Options =&gt;
        Options.UseMySql(
            configuration.GetConnectionString(&quot;UavHostileDb&quot;),
            ServerVersion.AutoDetect(configuration.GetConnectionString(&quot;UavHostileDb&quot;))));
service.AddScoped&lt;HostileUavProcessingService&gt;();
var serviceProvider = service.BuildServiceProvider();
Console.WriteLine(&quot;Creating database...&quot;);

using (var scope = serviceProvider.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService&lt;HostileUavDbContext&gt;();
    db.Database.EnsureCreated();
}
Console.WriteLine(&quot; Database ready\n&quot;);
var consumerConfig = new ConsumerConfig
{
    BootstrapServers = configuration[&quot;Kafka:BootsrapServers&quot;],
    GroupId = &quot;uav-consumer-group-123&quot;,
    AutoOffsetReset = AutoOffsetReset.Earliest,
    EnableAutoCommit = false
};

using var consumer = new ConsumerBuilder&lt;Ignore, string&gt;(consumerConfig).Build();

var modelsTopic = configuration[&quot;Kafka:Topic:UavModels&quot;] ?? &quot;models&quot;;
var hostileUnitsTopic = configuration[&quot;Kafka:Topic:HostileUnits&quot;] ?? &quot;hostileUnits&quot;;
var tracksTopic = configuration[&quot;Kafka:Topic:Tracks&quot;] ?? &quot;tracks&quot;;


try
{
    consumer.Subscribe(modelsTopic);
    while (true)
    {
        // Wait for a message (timeout after 10 second)
        var result = consumer.Consume(TimeSpan.FromSeconds(10));

        // If no message, continue waiting
        if (result == null || result.Message?.Value == null)
        {
            Console.WriteLine($&quot;Finished reading Topic {modelsTopic} or reached timeout.&quot;);
            break;

        }

        using var scope = serviceProvider.CreateScope();
        var processingService = scope.ServiceProvider.GetRequiredService&lt;HostileUavProcessingService&gt;();
        if (await processingService.ProcessUavModelsAsync(result.Message.Value))
        {
            Console.WriteLine(result.Message.Value);
            consumer.Commit(result);
        }
    }
    consumer.Unsubscribe();
    Console.WriteLine(&quot;Waiting for delay period...&quot;);
    await Task.Delay(TimeSpan.FromSeconds(10));



    consumer.Subscribe(hostileUnitsTopic);
    Console.WriteLine($&quot;Consuming Topic {hostileUnitsTopic}...&quot;);
    while (true)
    {
        var result = consumer.Consume(TimeSpan.FromSeconds(10));
        if (result == null || result.Message?.Value == null)
        {
            Console.WriteLine($&quot;Finished reading Topic {hostileUnitsTopic} or reached timeout.&quot;);
            break;

        }
        using var scope = serviceProvider.CreateScope();
        var processingService = scope.ServiceProvider.GetRequiredService&lt;HostileUavProcessingService&gt;();
        if (await processingService.ProcessHostileUnitsAsync(result.Message.Value))
        {
            Console.WriteLine(result.Message.Value);
            consumer.Commit(result);
        }
    }
    consumer.Unsubscribe();
    Console.WriteLine(&quot;Waiting for delay period...&quot;);
    await Task.Delay(TimeSpan.FromSeconds(10));



    consumer.Subscribe(tracksTopic);
    Console.WriteLine($&quot;Consuming Topic {tracksTopic}...&quot;);
    while (true)
    {
        var result = consumer.Consume(TimeSpan.FromSeconds(10));
        if (result == null || result.Message?.Value == null)
            continue;

        using var scope = serviceProvider.CreateScope();
        var processingService = scope.ServiceProvider.GetRequiredService&lt;HostileUavProcessingService&gt;();
        if (await processingService.ProcessTracksAsync(result.Message.Value))
        {
            Console.WriteLine(result.Message.Value);
            consumer.Commit(result);
        }
    }
}
catch (Exception ex)
{
    Console.WriteLine(ex);
}
finally
{
    consumer.Close();
    Console.WriteLine(&quot;Consumer closed.&quot;);
}
</code></pre>

Q: Explicit call to conversion function treated differently than implicit call when using explicit object parameter A: <p>This isn't so much an answer as a comment that's too large to fit into a comment.</p>
<p>But (for reasons I can't quite explain, yet, anyway) the compilers (g++ and clang++, anyway) aren't doing overload resolution at all, because they're not considering the template at all. For example, consider what happens if we change the non-template overload to take a reference to non-const:</p>
<pre class="lang-cpp prettyprint-override"><code>truct S {

    template&lt;typename T&gt;
    constexpr operator T(this S&amp;&amp;)     
    {
        return 10;
    }
    constexpr operator int(this S&amp;)
    {
        return 4;
    }

};

// static_assert( S{}==10);                          //#1 GCC OK, EDG OK, MSVC NO, Clang NO 
static_assert(S{}.operator int() ==10);        //#2 all compilers reject this 
</code></pre>
<p>In this case, there's no real question of whether one conversion sequence is preferred to the other--there's simply no conversion sequence to make the non-template overload viable at all. But rather than forcing selection of the template, this results in another error:</p>
<p>clang++:</p>
<pre><code>test.cpp:16:15: error: non-const lvalue reference to type 'S' cannot bind to a temporary of type 'S'
</code></pre>
<p>g++:</p>
<pre><code>test.cpp:16:15: error: cannot bind non-const lvalue reference of type ‘S&amp;’ to an rvalue of type ‘S’
</code></pre>
<p>So, for scenario #2, it's not a matter of creating an overload set, and choosing a conversion sequence that it shouldn't. Rather it appears that the template is never being considered at all.</p>
